import * as ui from "std/ui"

@jsonable
class LogEntry {
  voter: string;
  side: string;
  minute: number;
}

@jsonable
class AppState {
  entries: LogEntry[];
  draft_voter: string;
  draft_side: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_voter: "", draft_side: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function set_draft_voter(state: AppState, value: string): AppState {
  return {draft_voter: value, entries: state.entries, draft_side: state.draft_side, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_side(state: AppState, value: string): AppState {
  return {draft_side: value, entries: state.entries, draft_voter: state.draft_voter, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_voter) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {voter: strings.trim(state.draft_voter), side: strings.trim(state.draft_side), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_voter: "", draft_side: "", removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, draft_voter: state.draft_voter, draft_side: state.draft_side};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, draft_voter: state.draft_voter, draft_side: state.draft_side};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, entries: state.entries, draft_voter: state.draft_voter, draft_side: state.draft_side};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Would You Rather", "GROUP VOTE", "Pick a side and see how the group splits", ""));
  {
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = e.side + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.voter, sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Voter", state.draft_voter, "set_draft_voter"), ui.TextField("default", "Side", state.draft_side, "set_draft_side"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_voter) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Votes", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("playful", "", sections);
}

