import * as ui from "std/ui"

@jsonable
class LogEntry {
  guesser: string;
  correct: boolean;
  minute: number;
}

@jsonable
class AppState {
  playerCount: number;
  roundsPerPlayer: number;
  entries: LogEntry[];
  draft_guesser: string;
  draft_correct: boolean;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {playerCount: 4, roundsPerPlayer: 2, entries: emptyEntries, draft_guesser: "", draft_correct: false, removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_playerCount(state: AppState, value: number): AppState {
  return {playerCount: value, roundsPerPlayer: state.roundsPerPlayer, entries: state.entries, draft_guesser: state.draft_guesser, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_roundsPerPlayer(state: AppState, value: number): AppState {
  return {roundsPerPlayer: value, playerCount: state.playerCount, entries: state.entries, draft_guesser: state.draft_guesser, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_guesser(state: AppState, value: string): AppState {
  return {draft_guesser: value, playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, entries: state.entries, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_correct(state: AppState, value: boolean): AppState {
  return {draft_correct: value, playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, entries: state.entries, draft_guesser: state.draft_guesser, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_guesser) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {guesser: strings.trim(state.draft_guesser), correct: state.draft_correct, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_guesser: "", playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, draft_correct: state.draft_correct, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, draft_guesser: state.draft_guesser, draft_correct: state.draft_correct};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, draft_guesser: state.draft_guesser, draft_correct: state.draft_correct};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, playerCount: state.playerCount, roundsPerPlayer: state.roundsPerPlayer, entries: state.entries, draft_guesser: state.draft_guesser, draft_correct: state.draft_correct};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Two Truths and a Lie", "PARTY GAME", "Track turns and score the guesses", ""));
  {
      let playerCount: number = state.playerCount;
      let roundsPerPlayer: number = state.roundsPerPlayer;
      let pointsPerCorrect: number = 1;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      let totalTurns: number = playerCount * roundsPerPlayer;
      let currentTurn: number = (entryCount + 1);
      let progress: number = share(entryCount, totalTurns);
    sections.push(ui.Section("content", "", "", [ui.Progress("accent", "Game progress", math.round(math.min(math.max(progress, 0), 1) * 1000), 1000)]));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Players", state.playerCount, 2, 12, "set_playerCount"), ui.NumberField("default", "Rounds each", state.roundsPerPlayer, 1, 10, "set_roundsPerPlayer")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Total turns", totalTurns, "", "", 1, "", "chart", 0), ui.NumberStat("default", "Turn", currentTurn, "", "", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      if (e.correct) { sub = "Guessed right · " + sub; }
      rows.push(ui.ListItem("default", e.guesser, sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Guesser", state.draft_guesser, "set_draft_guesser"), ui.Toggle("default", "Guessed right", state.draft_correct, "set_draft_correct"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_guesser) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Turns played", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("playful", "", sections);
}

