function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_wateringInterval(state: AppState, value: number): AppState {
  return {wateringInterval: value, entries: state.entries, draft_plantName: state.draft_plantName, draft_wateredOn: state.draft_wateredOn, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
