}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_plantName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {plantName: strings.trim(state.draft_plantName), wateredOn: state.draft_wateredOn, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_plantName: "", wateringInterval: state.wateringInterval, draft_wateredOn: state.draft_wateredOn, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, wateringInterval: state.wateringInterval, draft_plantName: state.draft_plantName, draft_wateredOn: state.draft_wateredOn, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, wateringInterval: state.wateringInterval, draft_plantName: state.draft_plantName, draft_wateredOn: state.draft_wateredOn, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, wateringInterval: state.wateringInterval, entries: state.entries, draft_plantName: state.draft_plantName, draft_wateredOn: state.draft_wateredOn, settingsOpen: state.settingsOpen};
}







