class AppState {
  roommateCount: number;
  rotationWeeks: number;
  items7: Item[];
  settingsOpen: boolean;
}

function init(): AppState {
  let items7: Item[] = [
    {label: "Dishes", detail: "", done: false},
    {label: "Trash", detail: "", done: false},
    {label: "Vacuuming", detail: "", done: false},
    {label: "Bathroom", detail: "", done: false},
    {label: "Kitchen", detail: "", done: false},
    {label: "Laundry", detail: "", done: false},
    {label: "Dusting", detail: "", done: false},
    {label: "Mopping", detail: "", done: false}
  ];
  return {roommateCount: 4, rotationWeeks: 1, items7: items7, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_roommateCount(state: AppState, value: number): AppState {
  return {roommateCount: value, rotationWeeks: state.rotationWeeks, items7: state.items7, settingsOpen: state.settingsOpen};
}

function set_rotationWeeks(state: AppState, value: number): AppState {
  return {rotationWeeks: value, roommateCount: state.roommateCount, items7: state.items7, settingsOpen: state.settingsOpen};
}







function toggle7(state: AppState, index: number): AppState {
  let out: Item[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (i === index) {
      out.push({label: it.label, detail: it.detail, done: !it.done});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  return {items7: out, roommateCount: state.roommateCount, rotationWeeks: state.rotationWeeks, settingsOpen: state.settingsOpen};
}

function doneCount7(state: AppState): number {
  let n: number = 0;
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (it.done) { n = n + 1; }
    i = i + 1;
  }
  return n;
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, roommateCount: state.roommateCount, rotationWeeks: state.rotationWeeks, items7: state.items7};
}

